cat > /tmp/smoothsearch.py <<'PY'
# Build Euler routes without smoothing; raster sweep with adjustable smooth sigma and morphology
import numpy as np, cv2, math, networkx as nx
from PIL import Image
from scipy import ndimage as ndi
from scipy.ndimage import gaussian_filter1d
exec(open('/tmp/analyze.py').read().split('# graph endpoints')[0])
T=np.array(Image.open('/app/target.png').convert('L'))<128
components=[]
for k in range(1,num):
 x,y,w,h,a=st[k]
 if a<40: continue
 sk=thin(lab[y:y+h,x:x+w]==k); H,W=sk.shape; G=nx.Graph(); pts=list(map(tuple,np.argwhere(sk))); G.add_nodes_from(pts)
 for r,c in pts:
  for dr,dc in [(0,1),(1,0),(1,1),(1,-1)]:
   rr,cc=r+dr,c+dc
   if 0<=rr<H and 0<=cc<W and sk[rr,cc] and not(dr and dc and (sk[r,cc] or sk[rr,c])):G.add_edge((r,c),(rr,cc),weight=math.hypot(dr,dc))
 if not nx.is_connected(G): G=G.subgraph(max(nx.connected_components(G),key=len)).copy()
 odd=[v for v in G if G.degree(v)%2]; d=dict(nx.all_pairs_dijkstra_path_length(G,weight='weight')); M=nx.Graph(); M.add_nodes_from(odd)
 for i,u in enumerate(odd):
  for v in odd[i+1:]:M.add_edge(u,v,weight=-d[u][v])
 matching=nx.max_weight_matching(M,maxcardinality=True); MG=nx.MultiGraph(); MG.add_nodes_from(G.nodes)
 for u,v,z in G.edges(data=True):MG.add_edge(u,v,weight=z['weight'])
 for u,v in matching:
  pa=nx.shortest_path(G,u,v,weight='weight')
  for a,b in zip(pa,pa[1:]):MG.add_edge(a,b,weight=G[a][b]['weight'])
 route=list(nx.eulerian_circuit(MG,source=next(iter(G.nodes))))
 xy=np.array([(route[0][0][1]+x,route[0][0][0]+y)]+[(b[1]+x,b[0]+y) for a,b in route],float)
 components.append((k,(x,y,w,h),xy))

def raster(xy,yaw,half=9,rad=1):
 out=np.zeros((1024,1024),np.uint8); E=np.array([math.cos(-yaw),math.sin(-yaw)])*half
 for p0,p1 in zip(xy,xy[1:]):
  d=p1-p0; L=np.linalg.norm(d)
  if L<.01:continue
  poly=np.rint(np.array([p0+E,p1+E,p1-E,p0-E])).astype(np.int32)
  cv2.fillPoly(out,[poly],255)
 if rad:
  ker=cv2.getStructuringElement(cv2.MORPH_ELLIPSE,(2*rad+1,2*rad+1));out=cv2.dilate(out,ker)
 return out>0
best=(0,None)
for sig in [0,0.5,1,1.5,2,2.5,3,4,5]:
 for deg in np.arange(38,50.1,1):
  full=np.zeros((1024,1024),bool)
  for k,box,raw in components:
   xy=raw if sig==0 else np.column_stack([gaussian_filter1d(raw[:,0],sig,mode='wrap'),gaussian_filter1d(raw[:,1],sig,mode='wrap')])
   full |= raster(xy,np.deg2rad(deg),9,1)
  inter=(T&full).sum(); uni=(T|full).sum(); val=inter/uni
  if val>best[0]:best=(val,(sig,deg,full.sum(),int(inter),int(uni)))
 print('sigma',sig,'best-at',best)
